    private static FindingPostProcessor GetPostProcessor(ushort ruleIndex) => ruleIndex switch
    {
        169 => FindingPostProcessor.CredentialUri,
        171 => FindingPostProcessor.GenericUsername,
        462 => FindingPostProcessor.HomeDirectory,
        463 => FindingPostProcessor.CredentialUri,
        464 => FindingPostProcessor.GitIdentity,
        _ => FindingPostProcessor.Default,
    };
